<script setup lang="ts">
import { computed, ref } from 'vue'
import { webApi } from '../webApi'

const props = defineProps<{ data: any }>()
const emit = defineEmits<{ refresh: []; logout: [] }>()
const photoBusy = ref(false)
const error = ref('')
const eventIndex = ref(0)
const matchPage = ref(0)
const printEventId = ref('')
const upcoming = computed<any[]>(() => (props.data?.events || []).filter((e: any) => new Date(e.date).getTime() >= Date.now() - 86400000 && (!e.matches.length || e.matches.some(isPending))))
const event = computed(() => upcoming.value[Math.min(eventIndex.value, upcoming.value.length - 1)])
const matches = computed<any[]>(() => event.value?.matches?.filter(isPending) || [])
const pageCount = computed(() => Math.max(1, Math.ceil(matches.value.length / 2)))
const visibleMatches = computed(() => matches.value.slice(matchPage.value * 2, matchPage.value * 2 + 2))
const initials = computed(() => props.data.profile.name.trim().split(/\s+/).slice(0, 2).map((x: string) => x[0]).join(''))
function isPending(m: any) { return !m.winnerId && m.status !== 'completed' && !m.isBye }
function selectEvent(index: number) { eventIndex.value = index; matchPage.value = 0 }
function dateLabel(value: string) { if (!value) return 'ثبت نشده'; const d = new Date(value); return isNaN(d.getTime()) ? value : new Intl.DateTimeFormat('fa-IR', { dateStyle: 'medium', timeZone: 'Asia/Tehran' }).format(d) }
function dayDate(e: any, day: number) { return e.settings?.schedule?.days?.find((d: any) => d.day === day)?.date || e.date }
function weighTime(e: any) { if (!e?.weighInAt) return 'هنوز اعلام نشده'; return new Intl.DateTimeFormat('fa-IR', { dateStyle: 'medium', timeStyle: 'short', timeZone: 'Asia/Tehran' }).format(new Date(e.weighInAt)) }
function relativeTime(m: any) { return m?.scheduledStartMinute == null ? 'زمان تخمینی اعلام نشده' : `حدود ${m.scheduledStartMinute} دقیقه پس از شروع روز` }
function printCard(id: string) { printEventId.value = id; setTimeout(() => window.print(), 0) }
async function photoChanged(input: Event) {
  const file = (input.target as HTMLInputElement).files?.[0]
  if (!file) return
  error.value = ''
  if (!['image/jpeg', 'image/png'].includes(file.type) || file.size > 750000) { error.value = 'عکس JPG یا PNG زیر ۷۵۰ کیلوبایت انتخاب کنید'; return }
  photoBusy.value = true
  try { const photoData = await new Promise<string>((resolve, reject) => { const reader = new FileReader(); reader.onload = () => resolve(String(reader.result)); reader.onerror = reject; reader.readAsDataURL(file) }); await webApi().call('/athlete-portal/photo', 'PUT', { photoData }); emit('refresh') }
  catch (e: any) { error.value = e.message || 'ذخیره عکس ناموفق بود' }
  finally { photoBusy.value = false }
}
</script>

<template>
  <section dir="rtl" class="portal-shell">
    <div class="portal-layout">
      <header class="portal-header"><div class="portal-brand"><span class="brand-symbol">✦</span><span>باشگاه مسابقه</span><small>پنل ورزشکار</small></div><div class="header-actions"><button type="button" class="icon-button" title="به‌روزرسانی" @click="emit('refresh')">↻</button><button type="button" class="logout-button" @click="emit('logout')">خروج</button></div></header>

      <div class="profile-bar"><div class="avatar"><img v-if="data.profile.photoData" :src="data.profile.photoData" alt="عکس پرسنلی"><span v-else>{{ initials }}</span></div><div class="profile-name"><small>خوش اومدی، قهرمان 👋</small><h1>{{ data.profile.name }}</h1></div><div class="profile-info"><span>کد ملی <strong>{{ data.profile.nationalCode || 'ثبت نشده' }}</strong></span><span>تولد <strong>{{ data.profile.birthDate ? dateLabel(data.profile.birthDate) : 'ثبت نشده' }}</strong></span></div><label class="photo-button">{{ photoBusy ? 'در حال ذخیره…' : 'تغییر عکس' }}<input type="file" accept="image/png,image/jpeg" :disabled="photoBusy" @change="photoChanged"></label></div>
      <p v-if="error" class="error" role="alert">{{ error }}</p>

      <div class="content-intro"><div><span class="eyebrow">برنامه شخصی شما</span><h2>آمادهٔ مسابقه‌ای؟</h2></div><p>همه اطلاعاتی که برای حضور در زمین لازم داری، همین‌جاست.</p></div>

      <article v-if="event" class="event-card"><div class="event-heading"><div><span class="live-dot"></span><span class="event-kicker">مسابقه پیش رو</span><h3>{{ event.name }}</h3><p>{{ dateLabel(event.date) }}</p></div><div class="weight-badge"><small>دسته وزنی</small><strong>{{ event.weightCategory }}</strong></div></div>
        <div class="event-facts"><div class="fact"><div class="fact-icon">◷</div><div><small>وزن‌کشی دقیق</small><strong>{{ weighTime(event) }}</strong></div></div><div class="fact"><div class="fact-icon">▦</div><div><small>زمین بازی بعدی</small><strong>{{ matches[0]?.court ? `زمین ${matches[0].court}` : 'پس از قرعه‌کشی' }}</strong></div></div><div class="fact"><div class="fact-icon">#</div><div><small>تعداد بازی‌ها</small><strong>{{ matches.length }} بازی در برنامه</strong></div></div></div>
        <div class="schedule-heading"><div><span class="schedule-mark"></span><h4>برنامه بازی‌ها</h4><small>زمان‌ها تقریبی‌اند</small></div><span class="schedule-count">{{ matches.length }} بازی</span></div>
        <div class="schedule-list"><div v-for="(m, index) in visibleMatches" :key="m.id" class="schedule-row"><div class="game-number">{{ matchPage * 2 + index + 1 }}</div><div class="game-name"><strong>بازی {{ m.matchNumber || m.order }}</strong><span>{{ dateLabel(dayDate(event, m.day)) }}</span></div><div class="game-time"><strong>{{ relativeTime(m) }}</strong><span>زمین {{ m.court || 'نامشخص' }}</span></div></div><div v-if="!matches.length" class="schedule-empty">پس از قرعه‌کشی، زمان و زمین بازی‌ها اینجا نمایش داده می‌شود.</div></div>
        <div class="event-footer"><div class="pagination"><button type="button" :disabled="matchPage === 0" @click="matchPage--">→</button><span>{{ matchPage + 1 }} / {{ pageCount }}</span><button type="button" :disabled="matchPage >= pageCount - 1" @click="matchPage++">←</button></div><div class="footer-actions"><button v-if="upcoming.length > 1" type="button" class="switch-event" @click="selectEvent((eventIndex + 1) % upcoming.length)">رویداد بعدی ←</button><button v-if="matches.length" type="button" class="print-button" @click="printCard(event.id)">چاپ کارت حضور <span>↗</span></button></div></div>
      </article>
      <div v-else class="empty-card"><span>🥋</span><h3>فعلاً بازی در پیش نیست</h3><p>به محض ثبت مسابقه، برنامه اینجا نمایش داده می‌شود.</p></div>
      <p class="portal-note">برنامه ممکن است در طول مسابقه تغییر کند؛ پیش از حرکت به زمین، دکمهٔ به‌روزرسانی را بزن.</p>

      <div v-for="e in upcoming" :key="`print-${e.id}`" class="print-card" :class="{ selected: printEventId === e.id }"><div class="print-head"><span>کارت حضور ورزشکار</span><strong>{{ e.name }}</strong></div><div class="print-body"><img v-if="data.profile.photoData" :src="data.profile.photoData" alt="عکس ورزشکار"><div v-else class="print-photo">عکس پرسنلی<br>ثبت نشده</div><div><h2>{{ data.profile.name }}</h2><p>کد ملی: {{ data.profile.nationalCode || 'ثبت نشده' }}</p><p>تاریخ تولد: {{ data.profile.birthDate ? dateLabel(data.profile.birthDate) : 'ثبت نشده' }}</p><p>وزن: {{ e.weightKg != null ? `${e.weightKg} کیلوگرم` : `${e.weightCategory} (دسته وزنی)` }}</p><p>باشگاه: {{ data.profile.club || 'ثبت نشده' }}</p><p>وزن‌کشی: {{ weighTime(e) }}</p></div></div><div class="print-schedule"><strong>برنامه بازی‌ها</strong><div v-for="m in e.matches.filter(isPending)" :key="m.id"><span>بازی {{ m.matchNumber || m.order }} · زمین {{ m.court || 'نامشخص' }}</span><span>{{ dateLabel(dayDate(e, m.day)) }} · {{ relativeTime(m) }}</span></div></div><div class="print-foot">{{ e.name }} · {{ dateLabel(e.date) }}</div></div>
    </div>
  </section>
</template>

<style scoped>
